<?php require '../config.php';admin();$q=trim($_GET['q']??'');$st=$_GET['status']??'';$w=[];$p=[];if($q){$w[]='(ticket_no LIKE ? OR name LIKE ? OR email LIKE ? OR subject LIKE ?)';array_push($p,"%$q%","%$q%","%$q%","%$q%");}if(in_array($st,['open','pending','solved','closed'],true)){$w[]='status=?';$p[]=$st;}$s=db()->prepare("SELECT * FROM tickets ".($w?'WHERE '.implode(' AND ',$w):'')." ORDER BY updated_at DESC");$s->execute($p);$tickets=$s->fetchAll();$stats=db()->query("SELECT COUNT(*) total,SUM(status='open') open_n,SUM(status='pending') pending_n,SUM(status='solved') solved_n FROM tickets")->fetch();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin — DeskFlow</title><link rel="stylesheet" href="../assets/style.css"></head><body class="staff"><aside class="staffside"><a class="logo" href="../index.php"><span>desk</span>flow</a><a class="sideactive" href="index.php">Inbox</a><a href="articles.php">Knowledge base</a><a href="../index.php">View portal</a><a href="logout.php">Sign out</a></aside><main class="staffmain"><header class="staffhead"><div><small>WORKSPACE / INBOX</small><h1>Tickets</h1></div><a href="../request.php">+ New ticket</a></header><div class="statbar"><div><small>All</small><b><?=$stats['total']?></b></div><div><small>Open</small><b><?=$stats['open_n']?></b></div><div><small>Pending</small><b><?=$stats['pending_n']?></b></div><div><small>Solved</small><b><?=$stats['solved_n']?></b></div></div><form class="filterbar"><input name="q" value="<?=e($q)?>" placeholder="Search tickets..."><select name="status"><option value="">All statuses</option><?php foreach(['open','pending','solved','closed'] as $x):?><option <?=$st===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Filter</button></form><div class="inbox"><?php foreach($tickets as $t):?><a href="view.php?id=<?=$t['id']?>"><div class="initial"><?=e(strtoupper(substr($t['name'],0,1)))?></div><div class="inboxbody"><b><?=e($t['subject'])?></b><span><?=e($t['ticket_no'])?> · <?=e($t['name'])?></span><p><?=e(mb_strimwidth($t['message'],0,110,'…'))?></p></div><div class="inboxmeta"><span class="ticketstatus <?=e($t['status'])?>"><?=e($t['status'])?></span><small><?=e(date('M j H:i',strtotime($t['updated_at'])))?></small></div></a><?php endforeach;?></div></main></body></html>